package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;
public class RoadRetentionTest{
 public static void main(String[] args)throws Exception{Path dir=Paths.get(args[0]);NativeRoadHistory history=new NativeRoadHistory(Files.readAllBytes(dir.resolve("original-road-events.nrj")));int snapshots=0,cells=0,rejected=0;try(DirectoryStream<Path> files=Files.newDirectoryStream(dir,"race-background-*.nrb")){for(Path file:files){NativeSceneSnapshot scene=new NativeBackgroundScene(Files.readAllBytes(file)).sky.scene;byte[][] proofs=new byte[scene.geometryCount()][];for(int i=0;i<proofs.length;i++)proofs[i]=Files.readAllBytes(dir.resolve("owner-"+scene.geometry(i).serial+".nrp"));NativeRoadRetention retention=new NativeRoadRetention(scene,history,proofs);if(!retention.belongsTo(scene))throw new AssertionError("Scene binding");byte[] expected=Files.readAllBytes(dir.resolve("retention-"+scene.refresh+".ref"));ByteBuffer ref=ByteBuffer.wrap(expected).order(ByteOrder.LITTLE_ENDIAN);int count=ref.getInt();int[] actual=new int[38400];java.util.Arrays.fill(actual,-1);for(int i=0;i<retention.count();i++){NativeRoadRetention.Draw draw=retention.draw(i);int[] records=draw.records();ByteBuffer texture=retention.texture(draw);for(int j=0;j<records.length;j+=3){int at=records[j+1]*240+records[j];if(actual[at]>=0)throw new AssertionError("Duplicate owner");actual[at]=texture.get(records[j+2])&255;}}int found=0;for(int v:actual)if(v>=0)found++;if(found!=count||found!=retention.cells())throw new AssertionError("Coverage");for(int i=0;i<count;i++){int cell=ref.getInt(),value=ref.getInt();if(actual[cell]!=value)throw new AssertionError("Retained source value");}cells+=count;snapshots++;proofs[0]=proofs[0].clone();ByteBuffer.wrap(proofs[0]).order(ByteOrder.LITTLE_ENDIAN).putLong(24,scene.epoch+1);try{new NativeRoadRetention(scene,history,proofs);throw new AssertionError("Wrong epoch accepted");}catch(IllegalArgumentException expectedFailure){rejected++;}}}System.out.println("PASS_ROAD_RETENTION snapshots="+snapshots+" source_cells="+cells+" stale_rejected="+rejected);}
}
